import numpy as np
x=np.load('source_pixels.npz')['rgb'].astype(np.int16)
base=x[0]
for i in range(0,96,4):
 d=np.abs(x[i]-base).max(2)
 ys,xs=np.where(d>20)
 if len(xs): print(i, 'bbox',xs.min(),ys.min(),xs.max(),ys.max(),'count',len(xs),'mean',round(float(d[d>20].mean()),1))
 else: print(i,'none')
